crUpsertDish({"id":"veg-final-21","n":"Koshari égyptien","m":"Casserole","t":"55 min","s":["printemps","été","automne","hiver"],"servings":2,"cuisine":"égyptienne","family":"koshari","group":"vegetal","protein":"lentilles-pois-chiches","starch":"riz-pates","kind":"warm","texture":"moelleux-croustillant","technique":"cuissons séparées et assemblage","presentation":"assiette","vegetables":["tomate","oignon"],"lightness":"rassasiant","classic":true,"collections":["vegetarien"],"editorial":"pas-a-pas-debutant","i":[{"q":90,"u":"g","n":"riz","k":"riz"},{"q":80,"u":"g","n":"lentilles brunes","k":"lentilles brunes"},{"q":80,"u":"g","n":"petites pâtes","k":"petites pâtes"},{"q":120,"u":"g","n":"pois chiches cuits","k":"pois chiches cuits"},{"q":400,"u":"g","n":"tomates concassées","k":"tomates concassées"},{"q":2,"u":"","n":"oignons","k":"oignons"},{"q":2,"u":"","n":"gousses d’ail","k":"gousses d’ail"},{"q":1,"u":"c. à café","n":"cumin","k":"cumin"},{"q":1,"u":"c. à soupe","n":"vinaigre","k":"vinaigre"},{"q":2,"u":"c. à soupe","n":"huile","k":"huile"}],"p":["Cuire séparément lentilles, riz et pâtes afin que chaque élément garde sa texture.","Émincer les oignons et les faire dorer lentement dans l’huile jusqu’à ce qu’ils soient bruns et croustillants ; en réserver la moitié.","Faire revenir l’ail 30 secondes, ajouter tomates, cumin et vinaigre puis réduire 12 minutes.","Réchauffer les pois chiches dans la sauce tomate.","Mélanger riz, lentilles et pâtes dans deux bols.","Ajouter sauce, pois chiches puis les oignons croustillants."]},'vegetarien','noon');
