crUpsertDish({"id":"veg-final-51","n":"Socca niçoise, légumes rôtis et feta","m":"Four","t":"45 min","s":["printemps","été","automne","hiver"],"servings":2,"cuisine":"méditerranéenne","family":"socca-legumes-feta","group":"vegetal","protein":"pois-chiches-feta","starch":"farine-pois-chiches","kind":"warm","texture":"croustillant-moelleux","technique":"cuisson de socca et garniture","presentation":"assiette","vegetables":["courgette","poivron","tomate"],"lightness":"normal","classic":false,"collections":["vegetarien"],"editorial":"pas-a-pas-debutant","i":[{"q":140,"u":"g","n":"farine de pois chiches","k":"farine de pois chiches"},{"q":30,"u":"cl","n":"eau","k":"eau"},{"q":2,"u":"c. à soupe","n":"huile d’olive","k":"huile d’olive"},{"q":1,"u":"","n":"courgette","k":"courgette"},{"q":1,"u":"","n":"poivron","k":"poivron"},{"q":150,"u":"g","n":"tomates cerises","k":"tomates cerises"},{"q":80,"u":"g","n":"feta","k":"feta"}],"p":["Mélanger farine de pois chiches, eau, une cuillerée d’huile, sel et poivre puis reposer 20 minutes.","Rôtir courgette, poivron et tomates 20 minutes à 210 °C.","Chauffer une plaque ou poêle allant au four.","Verser la pâte en couche fine avec le reste d’huile.","Cuire 10 à 12 minutes très chaud puis passer sous le gril 2 minutes.","Garnir des légumes rôtis et de feta émiettée."]},'vegetarien','noon');
crUpsertDish({"id":"veg-final-52","n":"Involtini d’aubergine à la ricotta","m":"Four","t":"55 min","s":["printemps","été","automne","hiver"],"servings":2,"cuisine":"italienne","family":"involtini-aubergine","group":"vegetal","protein":"ricotta","starch":"aucun","kind":"warm","texture":"fondant","technique":"roulage et gratin","presentation":"assiette","vegetables":["aubergine","tomate"],"lightness":"normal","classic":false,"collections":["vegetarien"],"editorial":"pas-a-pas-debutant","i":[{"q":2,"u":"","n":"aubergines","k":"aubergines"},{"q":250,"u":"g","n":"ricotta","k":"ricotta"},{"q":40,"u":"g","n":"parmesan","k":"parmesan"},{"q":350,"u":"g","n":"coulis de tomate","k":"coulis de tomate"},{"q":1,"u":"","n":"œuf","k":"œuf"},{"q":null,"u":"","n":"basilic","k":"basilic"},{"q":1,"u":"c. à soupe","n":"huile d’olive","k":"huile d’olive"}],"p":["Couper les aubergines en longues tranches, les huiler légèrement et les rôtir 15 minutes à 210 °C.","Mélanger ricotta, œuf, moitié du parmesan et basilic.","Déposer une cuillerée de farce au bout de chaque tranche et rouler.","Verser le coulis dans un plat et ranger les rouleaux jointure dessous.","Ajouter le parmesan restant.","Cuire 20 à 25 minutes à 190 °C."]},'vegetarien','noon');
crUpsertDish({"id":"veg-final-53","n":"Mercimek köftesi, bouchées de lentilles corail","m":"Casserole","t":"45 min","s":["printemps","été","automne","hiver"],"servings":2,"cuisine":"turque","family":"mercimek-koftesi","group":"vegetal","protein":"lentilles","starch":"boulgour","kind":"warm","texture":"moelleux","technique":"cuisson puis façonnage","presentation":"assiette","vegetables":["oignon","herbes"],"lightness":"léger-rassasiant","classic":true,"collections":["vegetarien"],"editorial":"pas-a-pas-debutant","i":[{"q":160,"u":"g","n":"lentilles corail","k":"lentilles corail"},{"q":90,"u":"g","n":"boulgour fin","k":"boulgour fin"},{"q":1,"u":"","n":"oignon","k":"oignon"},{"q":1,"u":"c. à soupe","n":"concentré de tomate","k":"concentré de tomate"},{"q":1,"u":"c. à café","n":"cumin","k":"cumin"},{"q":2,"u":"c. à soupe","n":"persil et menthe","k":"persil et menthe"},{"q":1,"u":"","n":"citron","k":"citron"},{"q":1,"u":"c. à soupe","n":"huile d’olive","k":"huile d’olive"}],"p":["Cuire les lentilles dans 35 cl d’eau jusqu’à ce qu’elles soient presque défaites.","Hors du feu, ajouter le boulgour, couvrir et laisser gonfler 15 minutes.","Faire revenir l’oignon, ajouter concentré de tomate et cumin.","Mélanger avec lentilles et boulgour puis laisser tiédir.","Ajouter herbes et citron puis façonner des bouchées allongées avec les mains.","Servir tiède ou froid avec salade croquante."]},'vegetarien','noon');
crUpsertDish({"id":"veg-final-54","n":"Oignons farcis au riz, aux herbes et aux pignons","m":"Four","t":"1 h","s":["printemps","été","automne","hiver"],"servings":2,"cuisine":"méditerranéenne","family":"oignons-farcis-riz","group":"vegetal","protein":"pignons","starch":"riz","kind":"warm","texture":"fondant","technique":"blanchiment et farce","presentation":"assiette","vegetables":["oignon","tomate"],"lightness":"normal","classic":false,"collections":["vegetarien"],"editorial":"pas-a-pas-debutant","i":[{"q":4,"u":"","n":"gros oignons","k":"gros oignons"},{"q":120,"u":"g","n":"riz cuit","k":"riz cuit"},{"q":2,"u":"","n":"tomates","k":"tomates"},{"q":30,"u":"g","n":"pignons","k":"pignons"},{"q":2,"u":"c. à soupe","n":"persil et menthe","k":"persil et menthe"},{"q":30,"u":"g","n":"parmesan","k":"parmesan"},{"q":1,"u":"c. à soupe","n":"huile d’olive","k":"huile d’olive"}],"p":["Blanchir les oignons entiers 12 minutes puis laisser tiédir.","Les couper en deux et retirer délicatement le cœur en gardant deux couches extérieures.","Hacher les cœurs et les faire revenir avec tomate, riz, pignons et herbes.","Farcir les coques d’oignons et les ranger dans un plat.","Parsemer de parmesan et arroser légèrement d’huile.","Cuire 25 minutes à 190 °C."]},'vegetarien','noon');
crUpsertDish({"id":"veg-final-55","n":"Lobio géorgien aux haricots rouges et noix","m":"Cocotte","t":"50 min","s":["printemps","été","automne","hiver"],"servings":2,"cuisine":"géorgienne","family":"lobio","group":"vegetal","protein":"haricots-rouges","starch":"legumineuses","kind":"warm","texture":"crémeux-rustique","technique":"mijotage et écrasement","presentation":"assiette","vegetables":["oignon"],"lightness":"léger-rassasiant","classic":true,"collections":["vegetarien"],"editorial":"pas-a-pas-debutant","i":[{"q":450,"u":"g","n":"haricots rouges cuits","k":"haricots rouges cuits"},{"q":1,"u":"","n":"oignon","k":"oignon"},{"q":2,"u":"","n":"gousses d’ail","k":"gousses d’ail"},{"q":50,"u":"g","n":"noix","k":"noix"},{"q":1,"u":"c. à café","n":"coriandre moulue","k":"coriandre moulue"},{"q":1,"u":"c. à café","n":"paprika","k":"paprika"},{"q":1,"u":"c. à soupe","n":"vinaigre de vin","k":"vinaigre de vin"},{"q":null,"u":"","n":"coriandre fraîche","k":"coriandre fraîche"}],"p":["Faire fondre l’oignon 8 minutes puis ajouter ail et épices.","Ajouter les haricots avec 15 cl d’eau et mijoter 15 minutes.","Écraser grossièrement environ un tiers des haricots dans la cocotte.","Ajouter les noix finement concassées et cuire encore 5 minutes.","Hors du feu, ajouter vinaigre et coriandre fraîche.","Servir chaud ou tiède avec du pain."]},'vegetarien','noon');
crUpsertDish({"id":"veg-final-56","n":"Börek aux poireaux et à la feta","m":"Four","t":"50 min","s":["printemps","été","automne","hiver"],"servings":2,"cuisine":"turque","family":"borek-poireaux-feta","group":"vegetal","protein":"feta","starch":"pate-filo","kind":"warm","texture":"croustillant-fondant","technique":"pâte filo et farce","presentation":"assiette","vegetables":["poireau"],"lightness":"normal","classic":false,"collections":["vegetarien"],"editorial":"pas-a-pas-debutant","i":[{"q":6,"u":"","n":"feuilles de pâte filo","k":"feuilles de pâte filo"},{"q":2,"u":"","n":"poireaux","k":"poireaux"},{"q":180,"u":"g","n":"feta","k":"feta"},{"q":1,"u":"","n":"œuf","k":"œuf"},{"q":1,"u":"","n":"yaourt nature","k":"yaourt nature"},{"q":2,"u":"c. à soupe","n":"huile d’olive","k":"huile d’olive"},{"q":null,"u":"","n":"aneth","k":"aneth"}],"p":["Faire fondre les poireaux émincés 10 minutes et laisser refroidir.","Mélanger poireaux, feta émiettée, œuf, yaourt et aneth.","Superposer trois feuilles de filo légèrement huilées.","Répartir la farce, couvrir des trois autres feuilles et rabattre les bords.","Entailler seulement le dessus pour préformer les parts.","Cuire 25 à 30 minutes à 190 °C."]},'vegetarien','noon');
